%[text] # Seed Dynamics ODE Test
%[text] Integration harness for seed6DOFODE. Builds the same rectangular test seed used in Spinning\_Seed\_Dynamics\_Test.mlx, adds the fluid/gravity parameters required by the dynamics RHS (never set anywhere else), runs a full ode45 integration, then plots the resulting 3D trajectory and Euler-angle rates.
%[text] Sections: 1. Setup seed shape, mass, and environment parameters 2. Visualize seed shape (sanity check before integrating) 3. Run the dynamics (ode45) 4. Visualize the 3D trajectory and Euler-angle rates
addpath(genpath("physics"));
addpath("visualization");
%%
%[text] ## 1. Setup seed shape, mass, and environment parameters
%[text] Geometry & material parameters (matches Spinning\_Seed\_Dynamics\_Test.mlx)
spanLength    = 0.050;   % spanwise length,  body z (m)
chordLength   = 0.015;   % chord length,     body x (m)
thickness     = 0.002;   % plate thickness           (m)
bulkDensity   = 65;    % bulk material density     (kg/m^3)
arealDensity  = bulkDensity * thickness;   % areal density (kg/m^2)
totalDiasporeMass = spanLength*chordLength*thickness*bulkDensity;

% Strip discretisation
numStrips = 20;   % number of spanwise aerodynamic strips

% Time vector for the mass/inertia time series. Mass is constant for this
% symmetric seed (fixed nut), so a single sample is sufficient.
tSamples = 0;   % (s)

% Seed wing polyshape (drawing frame: x = spanwise, y = chordwise).
% Rectangle centred at the origin in both axes.
x_half = spanLength  / 2;   % half-span  in drawing x = body z (m)
y_half = chordLength / 2;   % half-chord in drawing y = body x (m)

wingPolyshape = polyshape( ...
    [-x_half,  x_half,  x_half, -x_half], ...   % drawing-x corners (spanwise)
    [-y_half, -y_half,  y_half,  y_half] );      % drawing-y corners (chordwise)

% Nut mass & position. Nut placed at the geometric centre -> body origin.
nutMass = 75e-6;         % kg
nutPos  = [0; 0; 0];    % body frame [x;y;z] (m)

% Assemble seedParamsIn
bsp.seedShape     = wingPolyshape;
bsp.seedDensity   = arealDensity;                        % (kg/m^2)
bsp.seedThickness = thickness;                           % (m)
bsp.numStrips     = numStrips;
bsp.tSamples      = tSamples;                             % (s)
bsp.nutMass_t     = nutMass * ones(size(tSamples));       % Nx1
bsp.nutPos_t      = repmat(nutPos, 1, numel(tSamples));   % 3xN

seedParamsIn.baseSeedParams = bsp;

% Build the full seed parameter struct: strip geometry, CoM(t), I_G(t), I_G_dot(t).
seedParams = setupSeedShapeAndMass(seedParamsIn);

% Environment parameters required by seed6DOFODE but not set by
% setupSeedShapeAndMass (see HANDOFF §4 "Required seedParams fields").
seedParams.rhoFluid = 1.225;   % fluid (air) density (kg/m^3)
seedParams.g        = 9.81;    % gravity magnitude (m/s^2)
% seedParams.aero is left unset -- computeAeroCoeffs falls back to its
% default (exact minimal_imp) empirical coefficients.

seedParams.enableSpanForce = true; %allow spanwise forces (false by default)
seedParams.enableSpanGeomVelocity = true; %allow geometric center COM velocity (false by default)
seedParams.enableSpanCOPMigration = true; %allow COP to migrate across span (false by default)
seedParams.enableSpanTorqueAttenuation = false; %allow torque attenuation (false by default)
seedParams.enableTxDamping = true; %additional damping in the roll direction (false by default)

%set the C_span value to change the spanwise forces/torques coefficient
%seedParams.aero = struct('C_Tx', 1);
%%
%[text] ## 2. Visualize seed shape
%[text] Sanity check: confirm the geometry looks right before integrating.
figure('Name', 'Seed shape sanity check'); %[output:4a9552b3]
visualizeSeedShape(seedParams, eye(3), [0;0;0], struct()); %[output:4a9552b3]
axis equal; grid on; %[output:4a9552b3]
xlim([-0.05 0.05]); ylim([-0.05 0.05]); zlim([-0.05 0.05]); %[output:4a9552b3]
xlabel('World X (m)'); ylabel('World Z (m)'); zlabel('World Y (m) -- up'); %[output:4a9552b3]
title('Seed geometry, identity pose'); %[output:4a9552b3]
view(35, 20); %[output:4a9552b3]
%%
%[text] ## 3. Run the dynamics
r0     = [0; 0; 0];
%q0     = [1; 0; 0; 0];
q0 = eul2quat([0 0 0],'XYZ')';
v0     = [0; 0; 0];
omega0 = [0;  10;  0];

x0 = [r0; q0; v0; omega0];

tspan = 0:0.003:10;   % integration horizon (s)

odeOpts = odeset('RelTol', 1e-6, 'AbsTol', 1e-8);
[tOut, xOut] = ode45(@(t, x) seed6DOFODE(t, x, seedParams), tspan, x0, odeOpts);

% xOut columns: [ r(1:3), q(4:7), v(8:10), omega(11:13) ]. ode45 discards the
% optional `intermediates` output of seed6DOFODE -- if per-strip quantities
% (alpha, CT, CD, ...) are needed later, re-call seed6DOFODE on each row of
% xOut in post-processing
%%
%[text] ## 4. Visualize the 3D trajectory and Euler-angle rates
%[text] \--- 3D CoM trajectory ---
visualizeSeedTrajectory(tOut, xOut(:,1:3).', xOut(:,4:7).'); %[output:701cde07] %[output:753c8186]
%%
%[text] ## 5. Visualize the output
traj.t             = tOut;
traj.quat          = xOut(:, 4:7).';
traj.comPos_world  = xOut(:, 1:3).';
traj.comVel_world  = xOut(:,8:10).';
traj.comOmega_body = xOut(:,11:13).';
% comPos_body omitted -> animateSeed falls back to massParams.com_t ([0;0;0]).

%set the output folder
outFolder = 'C:\Users\yohan\OneDrive\Documents\Research Stuff\Seed Dynamics Code\Outputs\Compiled_Outputs';

opts = struct();
opts.outputFolder = outFolder;
opts.videoFile    = fullfile(outFolder,'quick_Spin.mp4');
opts.fps          = 10;
opts.axisMode     = 'follow';
opts.zoomFactor   = 3;
opts.frameStep    = 5;
opts.showVels     = false;
opts.velOpts.showTotal     = false;    % total strip velocities
opts.velOpts.showProjected = false;
opts.velOpts.scale         = 0.04;

opts.figSize = [600 400];
opts.trajLineWidth = 1;
opts.shapeOpts.showCom = false;
opts.shapeOpts.showNut = false;

animateSeed(seedParams, traj, opts); %[output:553b801c] %[output:7485fecc]
%save the seed data to the same folder
seedRunData = struct('seedParams',seedParams,'x0',x0,'tOut',tOut,'xOut',xOut,'currDate',datetime('now'));
save(fullfile(outFolder,'quick_Spin.mat'),"seedRunData");

